import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
globalThis.sampleRate=48000;globalThis.AudioWorkletProcessor=class{constructor(){this.port={onmessage:null,postMessage(){}};}};
const url=new URL('./cortex-worklet.js',import.meta.url);let source=await readFile(url,'utf8');source=source.replace(/from '(\.\/[^']+)'/g,(_,path)=>"from '"+new URL(path,url).href+"'");
async function load(code,suffix){let Type;globalThis.registerProcessor=(_,p)=>{Type=p;};await import('data:text/javascript;base64,'+Buffer.from(code+'\n// '+suffix).toString('base64'));return Type;}
const Actual=await load(source,'actual'),Reference=await load(source.replace(/\*gain\*\.(?:125|25)/g,'*gain*.125'),'old-fixed-gain');
const envelope={attack:.03,decay:4,sustain:1,release:1};
function create(Type,wet=0,limit=8,output=.3){const p=new Type();p.port.onmessage({data:{type:'params',value:{active:true,binaural:true,difference:8,variation:0,octaves:0,reverb:wet,reverbSize:1,voiceLimit:limit,output,root:110}}});p.port.onmessage({data:{type:'state',voices:Float32Array.from({length:48},(_,i)=>i%3===0?1:0)}});return p;}
function render(p,seconds,collect=false){let power=0,count=0,peak=0;for(let b=0;b<Math.ceil(seconds*sampleRate/128);b++){const out=[new Float32Array(128),new Float32Array(128)];p.process([],[out]);for(const channel of out)for(const value of channel){assert.ok(Number.isFinite(value)&&Math.abs(value)<=1);peak=Math.max(peak,Math.abs(value));if(collect){power+=value*value;count++;}}}return{rms:Math.sqrt(power/(count||1)),peak};}
const actual=create(Actual),reference=create(Reference);for(const p of[actual,reference])p.port.onmessage({data:{type:'pulse',event:{group:0,strength:.65,envelope}}});render(actual,.6);render(reference,.6);const actualLevel=render(actual,.4,true),referenceLevel=render(reference,.4,true),ratio=actualLevel.rms/referenceLevel.rms;assert.ok(Math.abs(ratio-2)<1e-8,'single-pair level doubles against the fixed .125 reference');
const peaks=[];for(const wet of[0,1]){const p=create(Actual,wet,16,1);p.port.onmessage({data:{type:'params',value:{droneEnabled:true}}});for(let g=0;g<16;g++)p.startVoice(p.slots[g],{group:g,strength:1,choice:{legacy:false,noteIndex:0,octave:0,freeSemitones:0},envelope});const level=render(p,3,true);assert.ok(level.peak<=1);peaks.push({wet,peak:level.peak});p.port.onmessage({data:{type:'params',value:{active:false}}});render(p,.6);assert.equal(render(p,.1).peak,0);}
console.log(JSON.stringify({ok:true,singlePairGainRatio:ratio,gainDb:20*Math.log10(ratio),actualRms:actualLevel.rms,referenceRms:referenceLevel.rms,alignedSixteenPairPeaks:peaks,pauseSilence:true},null,2));
